use super::*;
use std::collections::VecDeque;
#[derive(Default)]struct Fake{responses:Mutex<VecDeque<Result<Value>>>,calls:Mutex<Vec<Value>>}
impl Transport for Fake{fn request(&self,base:&str,path:&str,token:Option<&str>,body:Option<Value>,query:&[(String,String)])->Result<Value>{self.calls.lock().unwrap().push(json!({"base":base,"path":path,"token":token,"body":body,"query":query}));self.responses.lock().unwrap().pop_front().expect("unexpected mocked request")}}
fn fixture()->(Weixin,Arc<Fake>,PathBuf){let dir=std::env::temp_dir().join(format!("floatboard-weixin-production-test-{}",uuid::Uuid::new_v4()));let fake=Arc::new(Fake::default());let service=Weixin::build(dir.join("weixin-production"),fake.clone(),false).unwrap();(service,fake,dir)}
fn push(f:&Fake,v:Value){f.responses.lock().unwrap().push_back(Ok(v));}
fn account()->Account{Account{generation:"generation-one".into(),token:"secret-token".into(),bot_id:"secret-bot".into(),login_user:"secret-user".into(),base:BASE.into(),..Account::default()}}
fn message(user:&str,bot:&str,text:&str)->Value{json!({"from_user_id":user,"to_user_id":bot,"message_type":1,"context_token":"secret-context","item_list":[{"type":1,"text_item":{"text":text}}]})}
#[test]fn stopped_poll_does_not_start_a_request(){let(w,f,dir)=fixture();w.call("start_login",&json!({})).unwrap();w.shutdown();step(&w.inner);assert!(f.calls.lock().unwrap().is_empty());drop(w);fs::remove_dir_all(dir).unwrap();}
#[test]fn strict_hosts(){for bad in ["http://ilinkai.weixin.qq.com","https://weixin.qq.com.evil.org","https://127.0.0.1","https://ilinkai.weixin.qq.com:444","https://u:p@ilinkai.weixin.qq.com","https://ilinkai.weixin.qq.com/path","https://ilinkai.weixin.qq.com?token=x"]{assert!(validate_base(bad).is_err());}assert!(validate_base(BASE).is_ok());}
#[test]fn login_binding_is_strict_and_send_has_stable_id(){let(w,f,dir)=fixture();push(&f,json!({"qrcode":"qr","qrcode_img_content":"local-qr-data"}));w.call("start_login",&json!({})).unwrap();step(&w.inner);push(&f,json!({"status":"confirmed","bot_token":"secret-token","ilink_bot_id":"secret-bot","ilink_user_id":"secret-user"}));step(&w.inner);let code=w.call("start_binding",&json!({})).unwrap()["binding_code"].as_str().unwrap().to_owned();assert_eq!(code.trim_start_matches("绑定 ").len(),32);push(&f,json!({"msgs":[message("attacker","secret-bot",&code),message("secret-user","wrong-bot",&code)]}));step(&w.inner);assert_eq!(w.call("snapshot",&json!({})).unwrap()["bound"],false);push(&f,json!({"msgs":[message("secret-user","secret-bot",&code)]}));step(&w.inner);let snap=w.call("snapshot",&json!({})).unwrap();assert_eq!(snap["bound"],true);assert!(!snap.to_string().contains("secret-"));let generation=snap["account_version"].as_str().unwrap();w.call("resume",&json!({})).unwrap();push(&f,json!({"ret":0}));assert_eq!(w.send(generation,"record-one","Task complete · fixture"),SendOutcome::Accepted);let calls=f.calls.lock().unwrap();let body=&calls.last().unwrap()["body"];assert_eq!(body["msg"]["client_id"],"floatboard-record-one");assert_eq!(body["msg"]["item_list"][0]["text_item"]["text"],"Task complete · fixture");drop(calls);assert!(w.call("send_test",&json!({"text":"arbitrary"})).is_err());w.call("disconnect",&json!({})).unwrap();assert_eq!(w.send(generation,"record-two","must not send"),SendOutcome::Failed);drop(w);fs::remove_dir_all(dir).unwrap();}
#[test]fn offline_dpapi_restore_and_halt(){let(w,f,dir)=fixture();{let mut s=w.inner.state.lock().unwrap();let mut a=account();a.recipient=a.login_user.clone();a.context="secret-context".into();s.account=Some(a);persist(&w.inner,&s).unwrap();}assert!(!String::from_utf8_lossy(&fs::read(dir.join("weixin-production/account.dpapi")).unwrap()).contains("secret-token"));drop(w);let w=Weixin::build(dir.join("weixin-production"),f.clone(),false).unwrap();step(&w.inner);assert!(f.calls.lock().unwrap().is_empty());assert_eq!(w.send("generation-one","id","title"),SendOutcome::Failed);w.call("resume",&json!({})).unwrap();w.halt().unwrap();step(&w.inner);assert!(f.calls.lock().unwrap().is_empty());assert_eq!(w.send("generation-one","id","title"),SendOutcome::Failed);drop(w);fs::remove_dir_all(dir).unwrap();}
#[test]fn ambiguous_send_is_unknown_and_explicit_error_is_terminal(){for ack in [json!({}),json!({"message_id":0}),json!({"message_id":"bad"})]{assert_eq!(classify_send(&ack),SendOutcome::Unknown);}assert_eq!(classify_send(&json!({"ret":0})),SendOutcome::Accepted);assert_eq!(classify_send(&json!({"message_id":"123"})),SendOutcome::Accepted);assert_eq!(classify_send(&json!({"ret":-14,"errmsg":"sensitive"})),SendOutcome::Failed);let(w,f,dir)=fixture();{let mut s=w.inner.state.lock().unwrap();let mut a=account();a.recipient=a.login_user.clone();a.context="secret-context".into();s.account=Some(a);s.active=true;}f.responses.lock().unwrap().push_back(Err("timeout secret-token".into()));assert_eq!(w.send("generation-one","stable","title"),SendOutcome::Unknown);assert_eq!(f.calls.lock().unwrap().len(),1);drop(w);fs::remove_dir_all(dir).unwrap();}
